namespace AdoBye.Samples.Kit;

/// <summary>
/// Glyph advance widths for the 14 standard PDF fonts, in 1/1000 em, matching
/// <c>reportlab.pdfbase.pdfmetrics.stringWidth(text, font, 1000)</c> (the width at size <c>s</c> is <c>Width * s / 1000</c>).
/// The tables derive from the Adobe core-14 AFM metrics (factual data). Text fonts encode through Windows-1252
/// (characters it cannot represent fall back to the Symbol/ZapfDingbats substitution widths, else the .notdef width of 761),
/// while Symbol and ZapfDingbats are looked up by Unicode code point. Tables were generated by a one-off script.
/// </summary>
public static class Std14Metrics
{
    private const int NotDef = 761;

    // Windows-1252 0x80..0x9F -> Unicode (0 = undefined).
    private static readonly char[] Cp1252High =
    {
        '\u20AC', '\0', '\u201A', '\u0192', '\u201E', '\u2026', '\u2020', '\u2021', '\u02C6', '\u2030', '\u0160', '\u2039', '\u0152', '\0', '\u017D', '\0',
        '\0', '\u2018', '\u2019', '\u201C', '\u201D', '\u2022', '\u2013', '\u2014', '\u02DC', '\u2122', '\u0161', '\u203A', '\u0153', '\0', '\u017E', '\u0178',
    };

    public static double Width(string baseFont, string text)
    {
        ArgumentNullException.ThrowIfNull(baseFont);
        ArgumentNullException.ThrowIfNull(text);
        if (!Fonts.TryGetValue(baseFont, out var font))
        {
            throw new ArgumentException($"Unknown standard font '{baseFont}'.", nameof(baseFont));
        }

        long sum = 0;
        for (var i = 0; i < text.Length; i++)
        {
            int cp = text[i];
            if (char.IsHighSurrogate(text[i]) && i + 1 < text.Length && char.IsLowSurrogate(text[i + 1]))
            {
                cp = char.ConvertToUtf32(text[i], text[i + 1]);
                i++;
            }

            sum += font.Bytes is null ? Sparse(font.Cps!, font.Widths!, cp) : TextWidth(font.Bytes, cp);
        }

        return sum;
    }

    private static int TextWidth(int[] table, int cp)
    {
        var b = ToCp1252(cp);
        return b >= 0 ? table[b] : Sparse(FallbackCps, FallbackWidths, cp);
    }

    private static int ToCp1252(int cp)
    {
        if (cp < 0x80 || (cp >= 0xA0 && cp <= 0xFF))
        {
            return cp;
        }

        if (cp is >= 0x80 and <= 0x9F or > 0xFFFF)
        {
            return -1;
        }

        var i = Array.IndexOf(Cp1252High, (char)cp);
        return i >= 0 && cp != 0 ? 0x80 + i : -1;
    }

    private static int Sparse(ushort[] cps, int[] widths, int cp)
    {
        if (cp > 0xFFFF)
        {
            return NotDef;
        }

        var i = Array.BinarySearch(cps, (ushort)cp);
        return i >= 0 ? widths[i] : NotDef;
    }

    private sealed record Font(int[]? Bytes, ushort[]? Cps, int[]? Widths);


